<?php
ini_set('display_errors','0');error_reporting(E_ALL);header('Content-Type: application/json; charset=utf-8');header('Cache-Control:no-store');$R=__DIR__.'/..';require "$R/lib/Db.php";require "$R/lib/Jwt.php";require "$R/lib/LineImageCompressor.php";$CFG=require "$R/config.php";
function out($x,$s=200){http_response_code($s);echo json_encode($x,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}function errx($x,$s=400){out(['error'=>$x],$s);}function userx(){global $CFG;$h=$_SERVER['HTTP_AUTHORIZATION']??'';if(!preg_match('/Bearer\s+(.+)/i',$h,$m))errx('توکن نامعتبر است',401);$p=Jwt::verify(trim($m[1]),$CFG['jwt_secret']);if(!$p)errx('توکن منقضی یا نامعتبر است',401);$u=Db::one("SELECT u.id,u.is_active,r.title role_title,r.is_admin FROM users u JOIN roles r ON r.id=u.role_id WHERE u.id=?",[$p['sub']]);if(!$u||!$u['is_active'])errx('کاربر نامعتبر',401);return $u;}
function missingLine(){ $cols=Db::all("SELECT COLUMN_NAME,DATA_TYPE,COLUMN_DEFAULT,IS_NULLABLE,EXTRA FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='lines' ORDER BY ORDINAL_POSITION");$v=[];$code='N/A-'.date('ymd').'-'.random_int(1000,9999);foreach($cols as $c){$n=$c['COLUMN_NAME'];if(stripos($c['EXTRA'],'auto_increment')!==false||$c['COLUMN_DEFAULT']!==null||$c['IS_NULLABLE']==='YES')continue;$type=strtolower($c['DATA_TYPE']);if(in_array($n,['code','line_code','number'],true))$v[$n]=$code;elseif(in_array($n,['title','name','origin','destination','description'],true))$v[$n]='ایستگاه ناموجود';elseif(in_array($n,['is_active','active','enabled'],true))$v[$n]=0;elseif(in_array($n,['is_auto_missing','auto_generated'],true))$v[$n]=1;elseif(str_contains($type,'int')||str_contains($type,'decimal')||str_contains($type,'float'))$v[$n]=0;elseif(str_contains($type,'date')||str_contains($type,'time'))$v[$n]=date('Y-m-d H:i:s');else $v[$n]='ایستگاه ناموجود';}if(!array_filter(array_keys($v),fn($x)=>in_array($x,['code','line_code','number'],true)))errx('ساخت خط خودکار ممکن نیست',500);$ns=array_keys($v);Db::run('INSERT INTO `lines`(`'.implode('`,`',$ns).'`) VALUES('.implode(',',array_fill(0,count($ns),'?')).')',array_values($v));$id=(int)Db::lastId();$exists=Db::all("SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='lines' AND COLUMN_NAME IN('is_active','active','enabled','is_auto_missing','auto_generated')");foreach($exists as $c){$n=$c['COLUMN_NAME'];if(in_array($n,['is_auto_missing','auto_generated'],true))Db::run("UPDATE `lines` SET `$n`=1 WHERE id=?",[$id]);else Db::run("UPDATE `lines` SET `$n`=0 WHERE id=?",[$id]);}return [$id,$code];}
function photo($v){if(!is_string($v)||$v==='')errx('تصویر تابلو الزامی است');if(strpos($v,'base64,')!==false)$v=base64_decode(substr($v,strpos($v,',')+1),true);if(!$v||strlen($v)>8*1024*1024||@getimagesizefromstring($v)===false)errx('تصویر نامعتبر یا بزرگ‌تر از ۸ مگابایت است');$rel='/uploads/line-locations/'.date('Y/m').'/';$dir=__DIR__.$rel;@mkdir($dir,0775,true);$p=$dir.'station-sign_'.bin2hex(random_bytes(8)).'.jpg';if(!LineImageCompressor::fromBinary($v,$p))errx('ذخیره تصویر ناموفق بود',500);return $rel.basename($p);}
$u=userx();$b=json_decode(file_get_contents('php://input'),true)?:$_POST;if(($b['station_status']??'')!=='missing')errx('این endpoint فقط برای ایستگاه ناموجود است');$lat=$b['latitude']??null;$lng=$b['longitude']??null;$acc=$b['accuracy_m']??null;if(!is_numeric($lat)||!is_numeric($lng)||!is_numeric($acc)||$lat<-90||$lat>90||$lng<-180||$lng>180||$acc<0||$acc>20)errx('مختصات یا دقت GPS نامعتبر است');$signs=$b['signs']??[];if(!is_array($signs)||!count($signs))errx('حداقل یک تابلو الزامی است');[$lid,$code]=missingLine();$now=date('Y-m-d H:i:s');Db::run('INSERT INTO line_station_locations(line_id,station_code,station_status,station_name,latitude,longitude,accuracy_m,captured_by,captured_at) VALUES(?,?,?,?,?,?,?,?,?)',[$lid,null,'missing','ایستگاه ناموجود',$lat,$lng,$acc,$u['id'],$now]);$sid=(int)Db::lastId();foreach($signs as $x){$tid=(int)($x['type_id']??0);if(!Db::one('SELECT id FROM station_sign_types WHERE id=? AND is_active=1',[$tid]))errx('نوع تابلو نامعتبر است');$p=photo($x['photo']??null);Db::run('INSERT INTO line_station_signs(station_location_id,sign_type_id,photo_path) VALUES(?,?,?)',[$sid,$tid,$p]);}out(['ok'=>true,'id'=>$sid,'line_id'=>$lid,'line_code'=>$code,'station_code'=>null,'station_status'=>'missing','updated_at'=>$now]);
